PentagonPaths::fill_left.body:
{
        self.left.clear();
        for &f in &fuse[a][b] {
            for &g in &fuse[f][c] {
                for &e in &fuse[g][d] {
                    self.left.push([e, f, g]);
                }
            }
        }
        self.left.sort_unstable();
    }

PentagonPaths::fill_right.body:
{
        for group in &mut self.right {
            group.clear();
        }
        for &l in &fuse[c][d] {
            for &k in &fuse[b][l] {
                for &e in &fuse[a][k] {
                    self.right[e].push([k, l]);
                }
            }
        }
        for group in &mut self.right {
            group.sort_unstable();
        }
    }

